// Shared lock with GitHub Actions. Stop the 8:40/5:40 fallback when this date+slot is claimed or posted.
const cfg = $('Config').first().json;
const resp = $input.first().json || {};
let doc = null;
const msg = String(resp.message || '');
if (resp.content) {
  try { doc = JSON.parse(Buffer.from(resp.content, 'base64').toString('utf8')); }
  catch (e) { throw new Error('Slot claim file was not valid JSON - fallback stopped to avoid a double post'); }
} else if (/not found/i.test(msg)) {
  doc = { claims: {} };
} else if (!msg) {
  doc = { claims: {} };
} else {
  throw new Error('Could not read _data/slot-claims.json (' + msg.slice(0, 180) + ') - fallback stopped to avoid a double post');
}
const key = cfg.today + ':' + cfg.slot;
const row = (doc.claims || {})[key] || null;
const status = row && String(row.status || '').toLowerCase();
const blocked = status === 'claimed' || status === 'posted';
return [{ json: { blocked, reason: blocked ? ('slot ' + key + ' is ' + status + (row.by ? ' by ' + row.by : '')) : ('slot ' + key + ' is free'), claim: row } }];

// ── Shared dedupe helpers (inlined into "Fetch RSS + Dedup"; also used by tests) ──
// n8n task runners have no URL global, so parse with a regex.
function parseUrl(u) {
  const m = String(u || '').trim().match(/^(https?):\/\/([^\/?#\s]+)([^?#\s]*)(\?[^#\s]*)?/i);
  return m ? { host: m[2].toLowerCase(), path: m[3] || '', query: (m[4] || '').slice(1) } : null;
}
function hostOf(u) { const p = parseUrl(u); return p ? p.host.replace(/^www\./, '') : ''; }
// Normalized source URL: no scheme, no www./m., no tracking/any query (except real ids), no trailing slash or /amp.
function canonUrl(u) {
  const p = parseUrl(u); if (!p) return String(u || '').trim().toLowerCase();
  const keep = p.query.split('&').filter(kv => /^(id|p|v|story|article|item)=/i.test(kv)).join('&');
  const path = p.path.replace(/\/amp\/?$/i, '').replace(/\/(index\.html?)$/i, '').replace(/\/+$/, '');
  return (p.host.replace(/^(www|m|amp)\./, '') + path + (keep ? '?' + keep : '')).toLowerCase();
}
const STOP = new Set(('a an the of to in on for and or with is are was were be been by at from as its it this that these those new says said say after over into how why what who when will can could would should just now ai '
  + 'about up out off than then their they them his her he she we you your our us not no yes more most report reports reportedly amid via vs here there has have had do does did get gets got make makes made '
  + 'launch launches launched announce announces announced unveil unveils unveiled').split(/\s+/));
function tokens(t) {
  return String(t || '').toLowerCase().replace(/[’']/g, '').replace(/[^a-z0-9$ ]/g, ' ').split(/\s+/)
    .filter(w => w.length > 1 && !STOP.has(w)).map(w => w.replace(/(ies)$/, 'y').replace(/([^s])s$/, '$1'));
}
function titleSim(a, b) {
  const A = new Set(tokens(a)), B = new Set(tokens(b));
  if (!A.size || !B.size) return { jac: 0, ovl: 0, shared: 0 };
  let i = 0; A.forEach(w => { if (B.has(w)) i++; });
  return { jac: i / (A.size + B.size - i), ovl: i / Math.min(A.size, B.size), shared: i };
}
// History entry: { src, title, url, canon, date }
const DAY = 86400000;
function cheapRepeat(cand, hist, opts) {
  const o = Object.assign({ jaccard: 0.6, overlap: 0.6, overlapMinShared: 3, overlapDays: 120 }, opts || {});
  const cu = canonUrl(cand.link || cand.url || '');
  for (const h of hist) {
    if (h.canon && cu && h.canon === cu) return { reason: 'same source URL', match: h };
  }
  for (const h of hist) {
    if (!h.title) continue;
    const s = titleSim(cand.title, h.title);
    if (s.jac >= o.jaccard) return { reason: 'similar title (jaccard ' + s.jac.toFixed(2) + ')', match: h };
    const recent = !h.date || (Date.now() - new Date(h.date).getTime()) < o.overlapDays * DAY;
    if (recent && s.shared >= o.overlapMinShared && s.ovl >= o.overlap) return { reason: 'similar title (overlap ' + s.ovl.toFixed(2) + ', ' + s.shared + ' shared words)', match: h };
  }
  return null;
}
const decodeEnt = s => String(s || '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/&#x([0-9a-f]+);/gi, (_, c) => String.fromCharCode(parseInt(c, 16))).replace(/&#(\d+);/g, (_, c) => String.fromCharCode(+c)).replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/<[^>]+>/g, '').trim();
// Website posts-index.json entries -> history entries
function siteHistory(posts) {
  return (posts || []).map(p => ({ src: 'site', title: p.headline || '', summary: (p.summary || '').slice(0, 160), url: p.sourceUrl || '', canon: p.sourceUrl ? canonUrl(p.sourceUrl) : '', date: p.publishedAt || p.date || null, slug: p.slug || '' }));
}
// aifeed.run/feed.xml (fallback when posts-index cannot be read)
function feedHistory(xml) {
  return (String(xml || '').match(/<item>[\s\S]*?<\/item>/gi) || []).map(b => {
    const g = re => decodeEnt((b.match(re) || [])[1] || '');
    const src = g(/<aifeed:sourceUrl>([\s\S]*?)<\/aifeed:sourceUrl>/i);
    return { src: 'site', title: g(/<title>([\s\S]*?)<\/title>/i), summary: g(/<description>([\s\S]*?)<\/description>/i).slice(0, 160), url: src, canon: src ? canonUrl(src) : '', date: g(/<pubDate>([\s\S]*?)<\/pubDate>/i) || null };
  }).filter(h => h.title);
}
// Instagram captions -> history entries (URL from the "Source" line, title = first line / hook)
function igHistory(media) {
  return (media || []).filter(m => m && m.caption).map(m => {
    const urls = (m.caption.match(/https?:\/\/[^\s<>"')]+/g) || []).map(u => u.replace(/[.,;:!?]+$/, '')).filter(u => !/aifeed\.run/i.test(u));
    const first = m.caption.split('\n').map(l => l.replace(/^[\s\u2800]+|[\s\u2800]+$/g, '')).find(l => l && !/^source:/i.test(l)) || '';
    const hook = first.replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, '').trim();
    const body = m.caption.replace(/\s+/g, ' ').slice(0, 220);
    return { src: 'instagram', title: hook, summary: body, url: urls[0] || '', canon: urls[0] ? canonUrl(urls[0]) : '', date: m.timestamp || null };
  });
}
function logHistory(history) {
  return ((history && history.posted) || []).map(p => ({ src: 'log', title: p.headline || '', url: p.url || '', canon: p.canonUrl || (p.url ? canonUrl(p.url) : ''), date: p.postedAt || p.date || null }));
}

// Loads the FULL posted history (website + Instagram + workflow log), fetches RSS, and removes anything
// already posted (same normalized source URL or similar title). A semantic same-event check runs later.
// (dedup_lib.js is prepended by build.py)
const cfg = $('Config').first().json;
const decode64 = r => { try { return r && r.content ? JSON.parse(Buffer.from(r.content, 'base64').toString('utf8')) : null; } catch (e) { return null; } };
const histResp = $('GH Get History').first().json || {};
const postsResp = $('GH Get Posts Index').first().json || {};
const history = decode64(histResp) || { posted: [], rankings: {} };
history.posted = history.posted || []; history.rankings = history.rankings || {};
const status = { website: null, instagram: null, log: history.posted.length };
const bust = u => u + (u.includes('?') ? '&' : '?') + 't=' + Date.now();

// (a) Website history (posts-index.json = every story on aifeed.run): GitHub API -> download_url (files >1MB have no
// inline content) -> raw.githubusercontent -> live site JSON, each tried twice.
let posts = decode64(postsResp);
let siteHist = null;
if (Array.isArray(posts) && posts.length) { siteHist = siteHistory(posts); status.website = 'github-api (' + posts.length + ')'; }
else {
  posts = null;
  const urls = [postsResp.download_url, `https://raw.githubusercontent.com/${cfg.repo}/${cfg.branch}/_posts/posts-index.json`, cfg.siteUrl + '/_posts/posts-index.json'].filter(Boolean);
  outer: for (const u of urls) for (let t = 0; t < 2; t++) {
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: bust(u), timeout: 20000 });
      const arr = typeof r === 'string' ? JSON.parse(r) : r;
      if (Array.isArray(arr) && arr.length) { posts = arr; siteHist = siteHistory(arr); status.website = hostOf(u) + ' (' + arr.length + ')'; break outer; }
    } catch (e) { /* retry / next source */ }
  }
}
// Safety rule: never post unless the website history loaded.
if (!siteHist || !siteHist.length) throw new Error('Dedupe safety stop: website post history could not be loaded (GitHub API, raw and site JSON all failed) - nothing posted');

// (b) Instagram captions (HTTP node retries once; on failure we continue with website + log only).
let igHist = [];
try {
  const media = $('IG Get Recent Media').all().flatMap(i => (i.json && Array.isArray(i.json.data)) ? i.json.data : []);
  igHist = igHistory(media);
  status.instagram = media.length ? 'ok (' + media.length + ' posts)' : 'FAILED - using website + log only';
} catch (e) { status.instagram = 'FAILED - using website + log only'; }

// (c) workflow's own posted log
const logHist = logHistory(history);
const allHist = [...siteHist, ...igHist, ...logHist];

const FEEDS = ['https://techcrunch.com/tag/artificial-intelligence/feed/','https://www.theverge.com/rss/ai-artificial-intelligence/index.xml','https://venturebeat.com/category/ai/feed/','https://www.wired.com/feed/tag/ai/latest/rss','https://www.technologyreview.com/feed/','https://www.artificialintelligence-news.com/feed/','https://spectrum.ieee.org/feeds/topic/artificial-intelligence.rss','https://www.zdnet.com/topic/artificial-intelligence/rss.xml','https://www.cnet.com/rss/ai/','https://www.cnbc.com/id/100727362/device/rss/rss.html','https://9to5google.com/feed/','https://9to5mac.com/feed/','https://arstechnica.com/ai/feed/','https://www.engadget.com/rss.xml','https://news.ycombinator.com/rss'];
const GENERAL_FROM = 11; // feeds from this index need an AI keyword filter
const AI_RE = /\b(ai|a\.i\.|artificial intelligence|gpt|llm|openai|anthropic|gemini|claude|chatgpt|copilot|nvidia|deepmind|mistral|llama|grok|xai|robot|agentic|agent|neural|generative|machine learning)\b/i;

async function feed(url, idx) {
  try {
    const raw = await this.helpers.httpRequest({ method: 'GET', url, timeout: 12000, headers: { 'User-Agent': 'Mozilla/5.0 AIFeedBot' } });
    const xml = typeof raw === 'string' ? raw : String(raw?.body || raw || '');
    const blocks = xml.match(/<item[\s>][\s\S]*?<\/item>/gi) || xml.match(/<entry[\s>][\s\S]*?<\/entry>/gi) || [];
    const out = [];
    for (const b of blocks.slice(0, 30)) {
      const title = decodeEnt((b.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '');
      const link = ((b.match(/<link[^>]*>\s*(https?:\/\/[^\s<]+)\s*<\/link>/i) || b.match(/<link[^>]+href="(https?:\/\/[^"]+)"/i) || b.match(/<guid[^>]*>(https?:\/\/[^\s<]+)<\/guid>/i) || [])[1] || '').trim();
      const dateStr = ((b.match(/<pubDate[^>]*>([\s\S]*?)<\/pubDate>/i) || b.match(/<(?:updated|published)[^>]*>([\s\S]*?)<\/(?:updated|published)>/i) || [])[1] || '').trim();
      const desc = decodeEnt(decodeEnt((b.match(/<description[^>]*>([\s\S]*?)<\/description>/i) || b.match(/<summary[^>]*>([\s\S]*?)<\/summary>/i) || [])[1] || '')).replace(/\s+/g, ' ').slice(0, 240);
      if (!title || title.length < 20 || !link) continue;
      const ts = dateStr ? new Date(dateStr).getTime() : NaN;
      if (!isNaN(ts) && Date.now() - ts > 36 * 3600000) continue;
      if (idx >= GENERAL_FROM && !AI_RE.test(title)) continue;
      out.push({ title, link, desc, publishedAt: isNaN(ts) ? null : new Date(ts).toISOString(), source: hostOf(link) });
    }
    return out;
  } catch (e) { return []; }
}
const res = await Promise.allSettled(FEEDS.map((u, i) => feed.call(this, u, i)));
const all = res.flatMap(r => r.status === 'fulfilled' ? r.value : []);

const fresh = [], skipped = [];
for (const it of all) {
  const cu = canonUrl(it.link);
  const rep = cheapRepeat(it, allHist);
  if (rep) { skipped.push({ title: it.title, reason: rep.reason, matched: `[${rep.match.src}] ${rep.match.title}`.slice(0, 140) }); continue; }
  if (fresh.some(f => f.canonUrl === cu || titleSim(f.title, it.title).jac >= 0.6)) continue;  // dedup inside this batch
  fresh.push({ ...it, canonUrl: cu });
  if (fresh.length >= 80) break;
}
if (!fresh.length) throw new Error('No fresh, non-duplicate stories found in RSS feeds - nothing posted');

// Compact "already posted" list for the ranking prompt and the semantic same-event check (last 90 days, site + IG + log).
const cutoff = Date.now() - 90 * DAY;
const compact = [];
const seenC = new Set();
for (const h of [...logHist, ...siteHist, ...igHist]) {
  const t = h.date ? new Date(h.date).getTime() : NaN;
  if (!isNaN(t) && t < cutoff) continue;
  const key = h.canon || h.title.toLowerCase();
  if (!h.title || seenC.has(key)) continue;
  seenC.add(key);
  compact.push({ src: h.src, date: isNaN(t) ? '' : new Date(t).toISOString().slice(0, 10), title: h.title.slice(0, 140), summary: (h.summary || '').slice(0, 140), outlet: hostOf(h.url) });
  if (compact.length >= 160) break;
}
const recentList = compact.slice(0, 60).map(c => '- ' + c.title).join('\n') || '- (none)';
const list = fresh.map((s, i) => `${i + 1}. ${s.title} (${s.source})`).join('\n');
const rankPrompt = `You are the editor of AIFeed.run, an Instagram + LinkedIn AI news brand.\nRank the best stories below for a broad AI-curious audience. Prefer: major launches, big numbers, policy/legal moves, surprising research, controversy with substance. Reject: opinion pieces, listicles, deals/discount posts, how-tos, rumors, minor updates, non-AI stories.\nMAX 1 story per company and per event.\nSEMANTIC DEDUP: exclude any story that covers the SAME underlying event as anything in "Already posted" even if worded differently or from a different outlet.\n\nAlready posted (most recent first):\n${recentList}\n\nCandidates:\n${list}\n\nReturn ONLY a JSON array (best first, up to 12): [{"index": <candidate number>, "score": <0-100>, "reason": "<short>"}]`;
return [{ json: { fresh, rankPrompt, history, historySha: histResp.sha || null, posts, postsSha: postsResp.sha || null, postedCompact: compact, dedupStatus: status, dedupSkipped: skipped.slice(0, 40), historyCounts: { site: siteHist.length, instagram: igHist.length, log: logHist.length } } }];

// Orders today's candidates (8am -> best story, 5pm -> best story not yet posted; the morning story is already
// removed by the dedupe) and builds the strict same-event prompt for up to 15 candidates.
const cfg = $('Config').first().json;
const base = $('Fetch RSS + Dedup').first().json;
const txt = $input.first().json?.content?.[0]?.text || '';
let ranked = [];
try { ranked = JSON.parse((txt.match(/\[[\s\S]*\]/) || ['[]'])[0]); } catch (e) { ranked = []; }
let ordered = ranked.map(r => base.fresh[parseInt(r.index) - 1]).filter(Boolean);
if (!ordered.length) ordered = base.fresh.slice(0, 12); // Claude failed -> recency order

const history = base.history;
if (cfg.slot === 2) {
  const morning = history.rankings[cfg.today];
  if (morning && morning.length) {
    // Morning ranking first (whatever of it is still unposted/fresh), then anything new from the fresh ranking.
    const fresh = new Set(base.fresh.map(f => f.canonUrl));
    const fromMorning = morning.filter(m => fresh.has(m.canonUrl));
    const seen = new Set(fromMorning.map(m => m.canonUrl));
    ordered = [...fromMorning.map(m => base.fresh.find(f => f.canonUrl === m.canonUrl)), ...ordered.filter(o => !seen.has(o.canonUrl))];
  }
} else {
  history.rankings[cfg.today] = ordered.slice(0, 12).map((o, i) => ({ rank: i + 1, title: o.title, canonUrl: o.canonUrl }));
}
// Pool for the semantic check: ranked stories, topped up with the next freshest unranked ones (so repeats can be replaced).
const pool = [...ordered];
for (const f of base.fresh) { if (pool.length >= 15) break; if (!pool.some(p => p.canonUrl === f.canonUrl)) pool.push(f); }
pool.splice(15);
if (!pool.length) throw new Error('No candidates left for slot ' + cfg.slot);
Object.keys(history.rankings).sort().slice(0, -14).forEach(k => delete history.rankings[k]);

const posted = base.postedCompact.map((p, i) => `P${i + 1}. [${p.date}${p.outlet ? ' ' + p.outlet : ''}] ${p.title}${p.summary && p.src !== 'instagram' ? ' - ' + p.summary : ''}`).join('\n');
const cands = pool.map((c, i) => `C${i + 1}. ${c.title} (${c.source})${c.desc ? ' - ' + c.desc.slice(0, 200) : ''}`).join('\n');
const sameEventPrompt = `You are a strict duplicate detector for an AI news account that must NEVER post the same news twice.
For EACH candidate, decide: is it the SAME NEWS EVENT as any item in ALREADY POSTED?
SAME event = same company/organization/person AND the same specific announcement, launch, deal, funding round, lawsuit, incident, research result, report or statement. It is still the same event if it comes from a different outlet, has a different headline or angle, or is a follow-up/analysis piece without a materially new development.
NOT the same event: a different product or announcement from the same company, a clearly new development (e.g. a ruling weeks after a lawsuit was filed), or merely the same general topic.
When unsure whether two items describe the same announcement, answer repeat=true.

ALREADY POSTED (P = posted on aifeed.run / Instagram; newest first):
${posted}

CANDIDATES:
${cands}

Return ONLY a JSON array with one object per candidate, in order:
[{"c": 1, "repeat": true|false, "match": "<P number of the matching posted item, or null>", "why": "<max 12 words>"}]`;
return [{ json: { pool, history, sameEventPrompt } }];

// Applies the semantic same-event verdicts: drops repeats, keeps the first 5 non-repeats as the candidates.
// Fails safe (no post) if the verdict is unreadable or every candidate is a repeat.
const { pool, history } = $('Pick Slot Story').first().json;
const compact = $('Fetch RSS + Dedup').first().json.postedCompact;
const txt = $input.first().json?.content?.[0]?.text || '';
let verdicts = null;
try { verdicts = JSON.parse((txt.match(/\[[\s\S]*\]/) || [''])[0]); } catch (e) { verdicts = null; }
if (!Array.isArray(verdicts) || !verdicts.length) throw new Error('Same-event check returned no readable verdict - nothing posted (safety stop)');
const byC = {}; verdicts.forEach(v => { const n = parseInt(String(v.c ?? v.candidate).replace(/\D/g, '')); if (n) byC[n] = v; });
const kept = [], skipped = [];
pool.forEach((c, i) => {
  const v = byC[i + 1];
  if (!v) { skipped.push({ title: c.title, reason: 'no verdict (treated as repeat)' }); return; }
  const isRep = v.repeat === true || String(v.repeat).toLowerCase() === 'true';
  if (isRep) {
    const m = parseInt(String(v.match || '').replace(/\D/g, ''));
    skipped.push({ title: c.title, reason: 'same event: ' + (v.why || ''), matched: compact[m - 1] ? compact[m - 1].title : (v.match || '') });
  } else kept.push(c);
});
const candidates = kept.slice(0, 5);
if (!candidates.length) throw new Error('All ' + pool.length + ' candidate stories were already posted (same news event) - nothing posted this run. Skipped: ' + skipped.map(s => s.title + ' => ' + (s.matched || s.reason)).join(' | ').slice(0, 900));
return [{ json: { candidates, history, sameEventSkipped: skipped } }];

// Verifies each candidate link loads; grabs og:image, site name, description and body text for fact-checking.
const { candidates, history } = $input.first().json;
const meta = (html, p) => { const m = html.match(new RegExp(`<meta[^>]+(?:property|name)=["']${p}["'][^>]+content=["']([^"']+)`, 'i')) || html.match(new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']${p}["']`, 'i')); return m ? m[1] : ''; };
const out = await Promise.all(candidates.map(async c => {
  let ok = false, html = '';
  try { html = String(await this.helpers.httpRequest({ method: 'GET', url: c.link, timeout: 25000, headers: { 'User-Agent': 'Mozilla/5.0 (Macintosh) AppleWebKit/537.36 Chrome/124 Safari/537.36' } })); ok = html.length > 2000; } catch (e) { ok = false; }
  const text = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 3500);
  return { ...c, linkOk: ok, ogImage: meta(html, 'og:image') || meta(html, 'twitter:image'), siteName: meta(html, 'og:site_name') || c.source, description: meta(html, 'og:description'), text };
}));
const usable = out.filter(c => c.linkOk);
if (!usable.length) throw new Error('All candidate source links failed to load');
const blocks = usable.map((c, i) => `### CANDIDATE ${i}\nHeadline: ${c.title}\nPublication: ${c.siteName}\nURL: ${c.link}\nFeed description: ${c.desc || c.description || '(none)'}\nArticle text (truncated): ${c.text}`).join('\n\n');
const captionPrompt = `For EACH candidate below write AIFeed.run social copy using ONLY facts stated in its article text. Return STRUCTURED parts only; our code assembles and formats the final captions, so do NOT include emojis except where stated, URLs, "Source" lines, hashtags inside text, or line breaks inside fields.

ACCURACY RULES (strict; copy that breaks them is rejected automatically):
- Keep every hedge from the source: considers, plans, reportedly, in talks, sources say, may, expected to, up to, proposed. If the source reports something as a plan, talks, a rumor or "sources say", the graphicHeadline, summary and igHook must ALL say so too (e.g. "DEEPSEEK WEIGHS DOUBLING ROUND TO UP TO $15B", not "DEEPSEEK DOUBLES FUNDING TO $15B").
- Never state a rumor, plan, proposal or report as done. Do not upgrade "up to" to an exact figure.
- Never invent details that are not in the article text (no "strong demand", motives, outcomes, quotes or numbers that are not there).
- Keep currency symbols and units exactly: "$15B" or "$15 billion", never "15 BILLION". Keep non-dollar currencies as written (e.g. "100 billion yuan").

Fields per candidate:
- igHook: one punchy line, starts with exactly one strong emoji (🚀💡🔥🤖⚡️📉📈⚠️🧠), max 18 words.
- igParagraphs: array of 3 or 4 short paragraphs, each 1-2 sentences, 15-45 words, conversational, no emojis.
- liHook: bold opening statement or surprising stat, no emoji, max 25 words.
- liParagraphs: array of 5 paragraphs (what happened; business/tech context; strategic implications; industry impact; outlook), each 2-4 sentences, 40-80 words.
- liTakeaway: one crisp takeaway sentence.
- igHashtags: exactly 5 hashtags without the # sign, letters/digits only (e.g. "OpenAI").
- liHashtags: exactly 5 professional hashtags, same format.
- outlet: publication name as it brands itself (e.g. "CNBC", "The Verge", "9to5Google").
- graphicHeadline: ALL CAPS, 4-8 words, punchy, factual, hedged when the source is hedged, $ kept on money. highlightWords: number of trailing words of graphicHeadline to color pink (1-3).
- summary: 1 sentence, 14-26 words.
- category: one of BUSINESS, MODELS, TOOLS, RESEARCH, POLICY, HARDWARE, SAFETY.
- supported: false if any claim is not in the article text, or the article is opinion, an ad, a rumor, or not about AI.
- safe: false for anything defamatory, graphic, or medical/financial advice.
- issues: short note.

${blocks}

Return ONLY a JSON array, one object per candidate in the same order:
[{"candidate":0,"igHook":"...","igParagraphs":["..."],"liHook":"...","liParagraphs":["..."],"liTakeaway":"...","igHashtags":["..."],"liHashtags":["..."],"outlet":"...","graphicHeadline":"...","highlightWords":2,"summary":"...","category":"...","supported":true,"safe":true,"issues":""}]`;
